# Initially generated by GitHub Copilot.
"""Check for vendoring provenance docs and copy scripts in destination repos.

Results written to out/vendoring_provenance_out.txt and
out/vendoring_provenance_out.json.
"""

import json
import sys
from pathlib import Path, PurePosixPath

from vendoring.discover import iter_inventory_seed_rows, provenance_dest_repos

_REPOS = Path(__file__).resolve().parents[3]
_MAM = _REPOS / "MAM-basics"
_OUT_TXT = _MAM / "out" / "vendoring_provenance_out.txt"
_OUT_JSON = _MAM / "out" / "vendoring_provenance_out.json"

PROVENANCE_NAMES = [
    "VENDORING.md",
    "vendoring.md",
    "VENDORS.md",
    "vendors.md",
    "vendored-from.md",
    "provenance.md",
    "PROVENANCE.md",
    "shared-with.md",
    "shared-with-MAM-basics.md",
    "copied-from.md",
    "vendored.md",
]

COPY_SCRIPT_PATTERNS = [
    "*copy*py*",
    "*vendor*py*",
    "*sync*py*",
    "*update_pycmn*",
]


def _to_repo_relative_posix(path: Path, repo_path: Path) -> str:
    return str(path.relative_to(repo_path)).replace("\\", "/")


def _candidate_scan_dirs_for_repo(repo: str) -> list[str]:
    """Return repo-relative directories to scan for provenance docs.

    Includes repo root (".") and parent directories of discovered vendored
    destination files for the repo, walking up to repo root for each path.
    """
    dirs: set[str] = {"."}
    for data in iter_inventory_seed_rows():
        if data["dest_repo"] != repo:
            continue
        dest_path = PurePosixPath(data["dest_path"])
        current = dest_path.parent if dest_path.suffix else dest_path
        while True:
            dirs.add(str(current))
            if current == PurePosixPath("."):
                break
            current = current.parent

    return sorted(dirs, key=lambda rel: (0 if rel == "." else 1, rel.count("/"), rel))


def _find_provenance_docs(repo: str, repo_path: Path) -> list[str]:
    found_docs: set[str] = set()
    for rel_dir in _candidate_scan_dirs_for_repo(repo):
        scan_dir = repo_path if rel_dir == "." else repo_path / rel_dir
        if not scan_dir.exists():
            continue
        for name in PROVENANCE_NAMES:
            path = scan_dir / name
            if path.exists() and path.is_file():
                found_docs.add(_to_repo_relative_posix(path, repo_path))
    return sorted(found_docs)


def _find_copy_scripts(repo_path: Path) -> list[str]:
    copy_scripts: set[str] = set()
    for pat in COPY_SCRIPT_PATTERNS:
        for hit in repo_path.rglob(pat):
            if not hit.is_file():
                continue
            if "__pycache__" in str(hit) or ".venv" in str(hit):
                continue
            copy_scripts.add(_to_repo_relative_posix(hit, repo_path))
    return sorted(copy_scripts)


def _scan_repo(repo: str) -> dict[str, object]:
    repo_path = _REPOS / repo
    scanned_dirs = _candidate_scan_dirs_for_repo(repo)
    found_docs = _find_provenance_docs(repo, repo_path)
    copy_scripts = _find_copy_scripts(repo_path)
    pycmn_dirs: list[dict[str, object]] = []

    for pycmn_rel in ["pycmn", "py/pycmn"]:
        pycmn_path = repo_path / pycmn_rel
        if not pycmn_path.exists():
            continue
        files = sorted(
            p.name
            for p in pycmn_path.iterdir()
            if p.suffix == ".py" and p.name != "__init__.py"
        )
        pycmn_dirs.append({"path": pycmn_rel, "files": files})

    return {
        "repo": repo,
        "scanned_dirs": scanned_dirs,
        "found_provenance_docs": found_docs,
        "copy_scripts": copy_scripts,
        "pycmn_dirs": pycmn_dirs,
    }


def main() -> None:
    sys.stdout.reconfigure(encoding="utf-8")
    repo_summaries = [_scan_repo(repo) for repo in provenance_dest_repos()]

    with _OUT_TXT.open("w", encoding="utf-8") as f:
        for summary in repo_summaries:
            repo = str(summary["repo"])
            f.write(f"\n=== {repo} ===\n")

            # Check for provenance docs
            found_docs = list(summary["found_provenance_docs"])
            if found_docs:
                f.write(f"  PROVENANCE DOCS: {found_docs}\n")
            else:
                f.write("  provenance docs: none\n")

            # Check for copy/sync scripts
            copy_scripts = list(summary["copy_scripts"])
            if copy_scripts:
                f.write(f"  COPY SCRIPTS: {copy_scripts}\n")
            else:
                f.write("  copy scripts: none found\n")

            # List pycmn directory if present at top level or common paths
            for pycmn_dir in list(summary["pycmn_dirs"]):
                f.write(f"  pycmn dir ({pycmn_dir['path']}): {pycmn_dir['files']}\n")

    json_payload = {"repos": repo_summaries}
    with _OUT_JSON.open("w", encoding="utf-8") as f:
        json.dump(json_payload, f, indent=2, ensure_ascii=False)
        f.write("\n")

    print(f"Wrote to {_OUT_TXT}")
    print(f"Wrote to {_OUT_JSON}")
